import { quotes, quoteLineItems, parts, laborServices, vatRates, sequences, customers } from '@/db/schema.js'

// ---------------------------------------------------------------------------
// Type definitions for API responses
// ---------------------------------------------------------------------------

type QuoteResponse = {
  id: string
  quoteNumber: string
  customerId: string | null
  status: 'draft' | 'sent' | 'converted' | 'rejected'
  notes: string | null
  lineItems: QuoteLineItemResponse[]
  createdAt: number
  updatedAt: number
}

type QuoteListResponse = {
  quotes: Array<{
    id: string
    quoteNumber: string
    customerId: string | null
    status: 'draft' | 'sent' | 'converted' | 'rejected'
    notes: string | null
    createdAt: number
    updatedAt: number
  }>
  total: number
}

type QuoteLineItemResponse = {
  id: string
  quoteId: string
  lineType: 'part' | 'labor' | 'bicycle'
  partId: string | null
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
  createdAt: number
}

type ErrorResponse = {
  error: string
  code?: 'NOT_FOUND' | 'QUOTE_NOT_DRAFT' | 'VALIDATION_ERROR' | 'INTERNAL_ERROR'
}

// ---------------------------------------------------------------------------
// Helper — reset all relevant tables between tests
// ---------------------------------------------------------------------------

async function resetTables() {
  await db.delete(quoteLineItems)
  await db.delete(quotes)
  await db.delete(sequences)
  await db.delete(parts)
  await db.delete(laborServices)
  await db.delete(vatRates)
  await db.delete(customers)
}

beforeEach(async () => {
  await resetTables()
})

