import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
  type SaleResult,
  InsufficientStockError,
  SaleNotFoundError,
  listSales,
  findSaleById,
  findLineItemsBySaleId,
  findPaymentsBySaleId,
  findMovementsBySaleId
} from '../services/sale.service.js'

const salesRoutes = new Hono()

// ============================================================================
// POST /sales — Create a direct sale
// ============================================================================

/**
 * Error response shape.
 */
interface ErrorResponse {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

salesRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result: SaleResult = await createDirectSale(rawInput)

    return c.json(
      {
        sale: Object.fromEntries(Object.entries(result.sale)),
        payment: Object.fromEntries(Object.entries(result.payment)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item)))
      },
      201
    )
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return c.json(
        {
          error: 'Insufficient stock',
          code: 'INSUFFICIENT_STOCK',
          shortfalls: err.shortfalls
        } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid sale input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /sales] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /sales — List recent sales history
// ============================================================================

interface SalesListResponse {
  /** Array of sale records (newest first) */
  sales: Record<string, unknown>[]
  /** Total count of all sales */
  total: number
}

salesRoutes.get('/', async (c) => {
  const limit = Math.min(parseInt(c.req.query('limit') ?? '50', 10) || 50, 200)

  const saleRows = await listSales(limit)
  const total = await listSales(999999).then(rows => rows.length)

  return c.json({
    sales: saleRows.map(row => Object.fromEntries(Object.entries(row))),
    total
  } as SalesListResponse)
})

// ============================================================================
// GET /sales/:id — Get a single sale with full details
// ============================================================================

interface SaleDetailResponse {
  /** The sale header */
  sale: Record<string, unknown>
  /** Line items for this sale */
  lineItems: Record<string, unknown>[]
  /** Payments allocated to this sale */
  payments: Record<string, unknown>[]
  /** Stock movements referencing this sale */
  stockMovements: Record<string, unknown>[]
}

salesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const sale = await findSaleById(id)
  if (!sale) {
    return c.json({ error: 'Sale not found', code: 'NOT_FOUND' }, 404)
  }

  const [lineItems, payments, stockMovements] = await Promise.all([
    findLineItemsBySaleId(id),
    findPaymentsBySaleId(id),
    findMovementsBySaleId(id)
  ])

  return c.json({
    sale: Object.fromEntries(Object.entries(sale)),
    lineItems: lineItems.map(item => Object.fromEntries(Object.entries(item))),
    payments: payments.map(payment => Object.fromEntries(Object.entries(payment))),
    stockMovements: stockMovements.map(mvmt => Object.fromEntries(Object.entries(mvmt)))
  } as SaleDetailResponse)
})

// ============================================================================
// PATCH /sales/:id/void — Void a completed sale
// ============================================================================

salesRoutes.patch('/:id/void', async (c) => {
  const id = c.req.param('id')

  try {
    const updatedSale = await voidSale(id)

    return c.json({
      sale: Object.fromEntries(Object.entries(updatedSale))
    })
  } catch (err) {
    if (err instanceof SaleNotFoundError) {
      return c.json(
        { error: 'Sale not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.includes('already voided')) {
      return c.json(
        { error: err.message, code: 'ALREADY_VOIDED' },
        409
      )
    }

    console.error('[PATCH /sales/:id/void] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

export default salesRoutes

import { Hono } from 'hono'
import {
  createQuote,
  getQuotesList,
  getQuoteById,
  updateQuote,
  deleteQuote,
  createQuoteLineItem,
  updateQuoteLineItem,
  deleteQuoteLineItem,
  type QuoteDetail,
  type CreateQuoteLineItemServiceInput,
  type UpdateQuoteLineItemServiceInput,
} from '../services/quote.service.js'

const quotesRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /quotes — List quotes with optional status filter
// ---------------------------------------------------------------------------

quotesRoutes.get('/', async (c) => {
  const statusFilter = c.req.query('status') as string | undefined

  try {
    const result = await getQuotesList(statusFilter)
    return c.json(result)
  } catch (err) {
    console.error('[GET /quotes] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// GET /quotes/:id — Get quote detail with line items
// ---------------------------------------------------------------------------

quotesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const quote = await getQuoteById(id)
    return c.json(quote as QuoteDetail)
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    console.error('[GET /quotes/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /quotes — Create a new draft quote
// ---------------------------------------------------------------------------

quotesRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    // Validate required fields
    if (!input || typeof input !== 'object') {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const quote = await createQuote({
      customerId: input.customerId ?? null,
      notes: input.notes ?? null,
    })

    return c.json(quote as QuoteDetail, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create quote'
    console.error('[POST /quotes] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /quotes/:id — Update draft fields only (customerId, notes)
// Draft-only enforcement: returns 403 if quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')
  const input = await c.req.json()

  try {
    // Validate request body
    if (!input || typeof input !== 'object') {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const quote = await updateQuote(id, {
      customerId: input.customerId ?? undefined,
      notes: input.notes ?? undefined,
    })

    return c.json(quote as QuoteDetail)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Update failed'
    const name = (err as { name?: string }).name || ''

    if (name === 'QuoteNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    if (name === 'QuoteNotDraftError') {
      return c.json({ error: message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    console.error('[PATCH /quotes/:id] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// DELETE /quotes/:id — Delete draft quote only
// Draft-only enforcement: returns 403 if quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.delete('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    await deleteQuote(id)
    return c.json({ message: 'Quote deleted successfully' })
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    if (err instanceof Error && err.name === 'QuoteNotDraftError') {
      return c.json({ error: err.message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    const message = err instanceof Error ? err.message : 'Delete failed'
    console.error('[DELETE /quotes/:id] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// POST /quotes/:quoteId/lines — Add line item to a quote
// Draft-only enforcement: returns 403 if parent quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.post('/:quoteId/lines', async (c) => {
  const quoteId = c.req.param('quoteId')
  const rawInput = await c.req.json()

  try {
    // Validate request body
    if (!rawInput || typeof rawInput !== 'object' || !rawInput.lineType) {
      return c.json({ error: 'Invalid request body — lineType is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const input = rawInput as CreateQuoteLineItemServiceInput
    const lineItem = await createQuoteLineItem(quoteId, input)

    return c.json(lineItem, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to create line item'
    const name = (err as { name?: string }).name || ''

    if (name === 'QuoteNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    if (name === 'QuoteNotDraftError') {
      return c.json({ error: message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    console.error('[POST /quotes/:quoteId/lines] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// PATCH /quotes/:quoteId/lines/:lineId — Update a line item
// Draft-only enforcement: returns 403 if parent quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.patch('/:quoteId/lines/:lineId', async (c) => {
  const quoteId = c.req.param('quoteId')
  const lineId = c.req.param('lineId')
  const rawInput = await c.req.json()

  try {
    // Validate request body
    if (!rawInput || typeof rawInput !== 'object' || !rawInput.lineType) {
      return c.json({ error: 'Invalid request body — lineType is required', code: 'VALIDATION_ERROR' }, 400)
    }

    const input = rawInput as UpdateQuoteLineItemServiceInput
    const lineItem = await updateQuoteLineItem(quoteId, lineId, input)

    return c.json(lineItem)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    const message = err instanceof Error ? err.message : 'Failed to update line item'
    const name = (err as { name?: string }).name || ''

    if (name === 'QuoteNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    if (name === 'QuoteNotDraftError') {
      return c.json({ error: message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    if (name === 'QuoteLineItemNotFoundError') {
      return c.json({ error: message, code: 'NOT_FOUND' }, 404)
    }

    console.error('[PATCH /quotes/:quoteId/lines/:lineId] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

// ---------------------------------------------------------------------------
// DELETE /quotes/:quoteId/lines/:lineId — Delete a line item
// Draft-only enforcement: returns 403 if parent quote is not in draft state
// ---------------------------------------------------------------------------

quotesRoutes.delete('/:quoteId/lines/:lineId', async (c) => {
  const quoteId = c.req.param('quoteId')
  const lineId = c.req.param('lineId')

  try {
    await deleteQuoteLineItem(quoteId, lineId)
    return c.json({ message: 'Line item deleted successfully' })
  } catch (err) {
    if (err instanceof Error && err.name === 'QuoteNotFoundError') {
      return c.json({ error: 'Quote not found', code: 'NOT_FOUND' }, 404)
    }

    if (err instanceof Error && err.name === 'QuoteNotDraftError') {
      return c.json({ error: err.message, code: 'QUOTE_NOT_DRAFT' }, 403)
    }

    if (err instanceof Error && err.name === 'QuoteLineItemNotFoundError') {
      return c.json({ error: 'Line item not found', code: 'NOT_FOUND' }, 404)
    }

    const message = err instanceof Error ? err.message : 'Delete failed'
    console.error('[DELETE /quotes/:quoteId/lines/:lineId] Unexpected error:', err)
    return c.json({ error: message, code: 'INTERNAL_ERROR' }, 500)
  }
})

export default quotesRoutes

